import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { fillPlateEstimate } from '@printforge/types';
import { FOOTPRINT_CHUNK_BYTES, parsePlateFootprint, readPlateFootprint } from './plate-footprint';

/** The top of an OrcaSlicer x1 file for Klipper: header, thumbnail, object defines, start G-code. */
const HEAD = [
  '; HEADER_BLOCK_START',
  '; generated by OrcaSlicer 2.3.0 on 2026-10-12 at 09:14:02',
  '; total layer number: 40',
  '; HEADER_BLOCK_END',
  '',
  '; THUMBNAIL_BLOCK_START',
  '; thumbnail begin 48x48 124',
  '; iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAYAAABXAvmHAAAAQ0lEQVR4Ae3BAQ0AAADCoPdPbQ43oAAA',
  '; thumbnail end',
  '; THUMBNAIL_BLOCK_END',
  '',
  'EXCLUDE_OBJECT_DEFINE NAME=whistle_body.stl_id_0_copy_0 CENTER=121.5,130 POLYGON=[[100,110],[143,110],[143,150],[100,150]]',
  'EXCLUDE_OBJECT_DEFINE NAME=whistle_cap.stl_id_1_copy_0 CENTER=155,125.25 POLYGON=[[148,118.5],[162,118.5],[162,132],[148,132]]',
  'M140 S60',
  'G28',
  'EXCLUDE_OBJECT_START NAME=whistle_body.stl_id_0_copy_0',
  'G1 X100 Y110 E0.4',
].join('\n');

const TAIL = [
  'G1 X143 Y150 E0.4',
  'M104 S0',
  '; filament used [g] = 7.41',
  '; estimated printing time (normal mode) = 23m 10s',
  '',
  '; CONFIG_BLOCK_START',
  '; nozzle_diameter = 0.4',
  '; printable_area = 0x0,260x0,260x260,0x260',
  '; printable_height = 300',
  '; printer_model = Creality Hi',
  '; CONFIG_BLOCK_END',
].join('\n');

const FOOTPRINT = { bbox: { x: 62, y: 40 }, printableArea: ['0x0', '260x0', '260x260', '0x260'] };

describe('parsePlateFootprint', () => {
  it('the union box of every object polygon (x 100..162, y 110..150) and the printable area', () => {
    expect(parsePlateFootprint(HEAD, TAIL)).toEqual(FOOTPRINT);
  });

  it('a small file read as one text gives the same', () => {
    expect(parsePlateFootprint(`${HEAD}\n${TAIL}`)).toEqual(FOOTPRINT);
  });

  it('feeds fillPlateEstimate: floor(260/67) x floor(260/45) = 15 in a grid, +20 % = 18', () => {
    const f = parsePlateFootprint(HEAD, TAIL);
    expect(fillPlateEstimate(f.bbox!, f.printableArea!, { cap: 100 })).toBe(18);
  });

  it('the purge tower is not part of the unit', () => {
    const withTower = `${HEAD}\nEXCLUDE_OBJECT_DEFINE NAME=wipe_tower CENTER=230,230 POLYGON=[[210,210],[250,210],[250,250],[210,250]]`;
    expect(parsePlateFootprint(withTower, TAIL).bbox).toEqual({ x: 62, y: 40 });
  });

  it('no defines, a define without a polygon, a flat polygon, garbage: no box; no readable printable_area: null', () => {
    expect(parsePlateFootprint('G28\nG1 X1 Y1', TAIL).bbox).toBeNull();
    expect(parsePlateFootprint('EXCLUDE_OBJECT_DEFINE NAME=a CENTER=1,1', TAIL).bbox).toBeNull();
    expect(parsePlateFootprint('EXCLUDE_OBJECT_DEFINE NAME=a POLYGON=[[5,5],[5,9]]', TAIL).bbox).toBeNull();
    expect(parsePlateFootprint('EXCLUDE_OBJECT_DEFINE NAME=a POLYGON=[[x,y],[,]]', TAIL).bbox).toBeNull();
    expect(parsePlateFootprint(HEAD, 'M104 S0').printableArea).toBeNull();
    expect(parsePlateFootprint(HEAD, '; printable_area = nonsense').printableArea).toBeNull();
    expect(parsePlateFootprint('', '')).toEqual({ bbox: null, printableArea: null });
  });
});

describe('readPlateFootprint', () => {
  let dir: string;
  beforeEach(() => { dir = fs.mkdtempSync(path.join(os.tmpdir(), 'pf-footprint-')); });
  afterEach(() => { fs.rmSync(dir, { recursive: true, force: true }); });

  it('a small file is read whole', async () => {
    const file = path.join(dir, 'x1.gcode');
    fs.writeFileSync(file, `${HEAD}\n${TAIL}`);
    await expect(readPlateFootprint(file)).resolves.toEqual(FOOTPRINT);
  });

  it('a large file: only its head and tail are read, so a define buried in the middle is not seen', async () => {
    const file = path.join(dir, 'big.gcode');
    const half = 'G1 X120.123 Y130.456 E0.01234\n'.repeat(Math.ceil((FOOTPRINT_CHUNK_BYTES * 1.5) / 30));
    const buried = 'EXCLUDE_OBJECT_DEFINE NAME=late CENTER=1,1 POLYGON=[[0,0],[259,0],[259,259],[0,259]]\n';
    fs.writeFileSync(file, `${HEAD}\n${half}${buried}${half}${TAIL}`);
    await expect(readPlateFootprint(file)).resolves.toEqual(FOOTPRINT);
  });

  it('a file that is not there: null', async () => {
    await expect(readPlateFootprint(path.join(dir, 'gone.gcode'))).resolves.toBeNull();
  });
});
